CREATE INDEX ix_review_items_workspace_id_status ON review_items (workspace_id, status);

CREATE TABLE run_events (
    run_id VARCHAR(40) NOT NULL, 
    seq INTEGER NOT NULL, 
    event VARCHAR(64) NOT NULL, 
    node_id VARCHAR(64), 
    payload JSONB NOT NULL, 
    id VARCHAR(40) NOT NULL, 
    workspace_id VARCHAR(40) NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    CONSTRAINT pk_run_events PRIMARY KEY (id), 
    CONSTRAINT fk_run_events_run_id FOREIGN KEY(run_id) REFERENCES runs (id), 
    CONSTRAINT fk_run_events_workspace_id FOREIGN KEY(workspace_id) REFERENCES workspaces (id), 
    CONSTRAINT uq_run_events_run_id_seq UNIQUE (run_id, seq)
);

CREATE INDEX ix_run_events_workspace_id ON run_events (workspace_id);

CREATE TABLE run_results (
    run_id VARCHAR(40) NOT NULL, 
    classification JSONB, 
    fields JSONB NOT NULL, 
    checks JSONB NOT NULL, 
    path JSONB, 
    overlays JSONB, 
    corrections JSONB, 
    workspace_id VARCHAR(40) NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    CONSTRAINT pk_run_results PRIMARY KEY (run_id), 
    CONSTRAINT fk_run_results_run_id FOREIGN KEY(run_id) REFERENCES runs (id), 
    CONSTRAINT fk_run_results_workspace_id FOREIGN KEY(workspace_id) REFERENCES workspaces (id)
);

CREATE INDEX ix_run_results_workspace_id ON run_results (workspace_id);

CREATE TABLE run_steps (
    run_id VARCHAR(40) NOT NULL, 
    node_id VARCHAR(64) NOT NULL, 
    seq INTEGER NOT NULL, 
    status VARCHAR(32) NOT NULL, 
    attempt INTEGER NOT NULL, 
    started_at TIMESTAMP WITH TIME ZONE, 
    finished_at TIMESTAMP WITH TIME ZONE, 
    duration_ms INTEGER, 
    output_port VARCHAR(64), 
    output JSONB, 
    usage JSONB, 
    error JSONB, 
    id VARCHAR(40) NOT NULL, 
    workspace_id VARCHAR(40) NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    CONSTRAINT pk_run_steps PRIMARY KEY (id), 
    CONSTRAINT fk_run_steps_run_id FOREIGN KEY(run_id) REFERENCES runs (id), 
    CONSTRAINT fk_run_steps_workspace_id FOREIGN KEY(workspace_id) REFERENCES workspaces (id), 
    CONSTRAINT uq_run_steps_run_id_node_id_attempt UNIQUE (run_id, node_id, attempt)
);

CREATE INDEX ix_run_steps_run_id ON run_steps (run_id);

CREATE INDEX ix_run_steps_workspace_id ON run_steps (workspace_id);

CREATE TABLE knowledge_documents (
    collection_id VARCHAR(40) NOT NULL, 
    document_id VARCHAR(40), 
    filename VARCHAR(500) NOT NULL, 
    mime_type VARCHAR(200), 
    size_bytes BIGINT, 
    chunk_count INTEGER NOT NULL, 
    status VARCHAR(32) NOT NULL, 
    error TEXT, 
    id VARCHAR(40) NOT NULL, 
    workspace_id VARCHAR(40) NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    CONSTRAINT pk_knowledge_documents PRIMARY KEY (id), 
    CONSTRAINT fk_knowledge_documents_collection_id FOREIGN KEY(collection_id) REFERENCES knowledge_collections (id), 
    CONSTRAINT fk_knowledge_documents_document_id FOREIGN KEY(document_id) REFERENCES documents (id), 
    CONSTRAINT fk_knowledge_documents_workspace_id FOREIGN KEY(workspace_id) REFERENCES workspaces (id)
);

CREATE INDEX ix_knowledge_documents_collection_id ON knowledge_documents (collection_id);

CREATE INDEX ix_knowledge_documents_document_id ON knowledge_documents (document_id);

CREATE INDEX ix_knowledge_documents_workspace_id ON knowledge_documents (workspace_id);

